/*
  src/App.js
  -----------
  The ROOT component of the React application.
  This is the top-level component — it owns all the shared state
  and passes data down to child components as props.

  COMPONENT TREE:
    App
    ├── SearchBar  (input + button + options)
    └── ResultsList
        └── PaperCard × N  (one per paper)

  STATE LIVES HERE because:
    - SearchBar needs to trigger searches
    - ResultsList needs to display results
    - Both are siblings — they can't share state directly
    - The parent (App) holds the state and passes it to both
    This pattern is called "lifting state up" in React.

  WHAT IS useState?
  ─────────────────
  const [variable, setVariable] = useState(initialValue)

  - variable    → read the current value
  - setVariable → call this to UPDATE the value
  - When setVariable() is called, React re-renders the component

  We have 4 pieces of state:
    papers    — the search results array
    loading   — true while fetching
    error     — error message string (or null)
    lastQuery — what was last searched (for display)

  WHAT IS useEffect?
  ───────────────────
  useEffect runs AFTER the component renders.
  It's used for side effects: API calls, subscriptions, timers.

  useEffect(() => {
    // code to run
  }, [dependencies])

  The second argument [] controls WHEN it runs:
    []          → runs once when component first mounts
    [value]     → runs when 'value' changes
    no array    → runs after every render (careful!)
*/

import React, { useState, useEffect } from 'react';
import SearchBar from './components/SearchBar';
import ResultsList from './components/ResultsList';
import { searchPapers, checkHealth } from './services/api';
import './App.css';

function App() {

  // ── State declarations ──────────────────────────────────────────────────

  const [papers, setPapers] = useState([]);
  // papers: array of paper objects from the API
  // [] = empty array initially (no results yet)

  const [loading, setLoading] = useState(false);
  // loading: true while the API call is in progress
  // Used to show spinner and disable the search button

  const [error, setError] = useState(null);
  // error: null = no error, or a string message to display
  // Set when the API call fails

  const [lastQuery, setLastQuery] = useState('');
  // Stores the last search term for display in results header

  const [sourceUsed, setSourceUsed] = useState('');
  // Which API source was actually used (shown in results header)

  const [summariesOn, setSummariesOn] = useState(false);
  // Whether summaries were enabled for the last search

  const [totalResults, setTotalResults] = useState(0);
  // Total count from API response

  const [hasSearched, setHasSearched] = useState(false);
  // Tracks if user has searched at all (to show empty state vs hero)

  const [backendStatus, setBackendStatus] = useState(null);
  // Health check result — shows which features are available


  // ── Effects ────────────────────────────────────────────────────────────

  useEffect(() => {
    /*
      Run health check when app loads.
      [] means: run ONCE when component first mounts.

      We don't block the UI — we just check silently
      and show a warning if the backend is unreachable.
    */
    const runHealthCheck = async () => {
      try {
        const health = await checkHealth();
        setBackendStatus(health);
      } catch {
        // Backend is not running — show a warning
        setBackendStatus({ status: 'offline' });
      }
    };
    runHealthCheck();
  }, []); // ← empty array = run once on mount


  // ── Handlers ───────────────────────────────────────────────────────────

  /*
    handleSearch()
    ──────────────
    Called by SearchBar when user submits a search.
    This is where the API call happens.

    Parameters:
      query     — search term
      source    — "arxiv", "semantic_scholar", "auto"
      summarize — boolean

    async/await flow:
      1. setLoading(true)   → spinner appears, button disabled
      2. await searchPapers() → waits for FastAPI response
      3. setPapers(data)    → results appear
      4. setLoading(false)  → spinner disappears

    try/catch:
      try   → attempt the API call
      catch → handle any error (network, server, etc.)
  */
  const handleSearch = async (query, source, summarize) => {
    setLoading(true);    // Show spinner
    setError(null);      // Clear previous errors
    setHasSearched(true);

    try {
      // This line PAUSES until FastAPI responds
      const data = await searchPapers(query, 10, source, summarize);

      // Update all state with the response
      setPapers(data.papers || []);
      setTotalResults(data.total || 0);
      setSourceUsed(data.source_used || source);
      setSummariesOn(data.summaries_enabled || false);
      setLastQuery(query);

    } catch (err) {
      /*
        err is an Axios error object.

        err.response        → server responded with an error (4xx, 5xx)
        err.response.data   → the error body from FastAPI
        err.code === 'ECONNABORTED' → request timed out
        err.message         → generic error message
      */
      console.error('Search failed:', err);

      if (!err.response) {
        // No response = backend is not running
        setError(
          '❌ Cannot connect to backend. Make sure FastAPI is running: uvicorn app.main:app --reload'
        );
      } else if (err.response.status === 503) {
        setError(
          '⚠️ API service unavailable. ' + (err.response.data?.detail || 'Try switching source to arXiv.')
        );
      } else {
        setError(`Error: ${err.response?.data?.detail || err.message}`);
      }

      setPapers([]); // Clear old results on error

    } finally {
      setLoading(false); // Always stop spinner, success OR failure
    }
  };


  // ── Render ─────────────────────────────────────────────────────────────

  return (
    <div className="app">

      {/* Decorative background blobs */}
      <div className="bg-blob blob-1"></div>
      <div className="bg-blob blob-2"></div>
      <div className="bg-blob blob-3"></div>

      {/* ── Header ── */}
      <header className="app-header">
        <div className="header-content">
          <div className="logo-area">
            <span className="logo-icon">⚗️</span>
            <div>
              <h1 className="app-title">Research Finder</h1>
              <p className="app-subtitle">AI-powered academic paper discovery</p>
            </div>
          </div>

          {/* Backend status indicator */}
          {backendStatus && (
            <div className={`status-dot ${backendStatus.status === 'ok' ? 'online' : 'offline'}`}>
              <span className="dot-pulse"></span>
              {backendStatus.status === 'ok' ? 'Backend online' : 'Backend offline'}
            </div>
          )}
        </div>
      </header>

      {/* ── Main content ── */}
      <main className="app-main">

        {/* Hero section — shown before first search */}
        {!hasSearched && (
          <div className="hero-section">
            <h2 className="hero-title">
              Discover research papers<br />
              <span className="hero-accent">powered by AI</span>
            </h2>
            <p className="hero-desc">
              Search millions of academic papers from arXiv and Semantic Scholar.
              Get AI-generated summaries to quickly understand what each paper is about.
            </p>
            <div className="hero-examples">
              <span className="hero-label">Try searching:</span>
              {/*
                These chips call handleSearch when clicked.
                They pass a preset query directly.
              */}
              {[
                'medical image segmentation',
                'large language models',
                'quantum computing',
                'climate change AI',
              ].map((example) => (
                <button
                  key={example}
                  className="example-chip"
                  onClick={() => handleSearch(example, 'arxiv', true)}
                >
                  {example}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Search bar — always visible */}
        <div className={`search-wrapper ${hasSearched ? 'compact' : ''}`}>
          <SearchBar onSearch={handleSearch} loading={loading} />
        </div>

        {/* Error message */}
        {error && (
          <div className="error-banner">
            <span className="error-icon">⚠️</span>
            <span>{error}</span>
            <button className="error-close" onClick={() => setError(null)}>✕</button>
          </div>
        )}

        {/* Loading skeleton */}
        {loading && (
          <div className="loading-state">
            <div className="loading-spinner-large"></div>
            <p className="loading-text">Searching papers...</p>
            <p className="loading-subtext">Fetching and summarizing results</p>
          </div>
        )}

        {/* Results */}
        {!loading && hasSearched && (
          <ResultsList
            papers={papers}
            query={lastQuery}
            total={totalResults}
            sourceUsed={sourceUsed}
            summariesOn={summariesOn}
          />
        )}

      </main>

      {/* ── Footer ── */}
      <footer className="app-footer">
        <p>Built with FastAPI + React · Data from arXiv & Semantic Scholar · Summaries by BART</p>
      </footer>

    </div>
  );
}

/*
  export default App
  ──────────────────
  Makes this component importable in other files.
  index.js imports App and renders it to the DOM.
*/
export default App;
